    from armoriq_sdk import ArmorIQClient, SessionOptions

    client = ArmorIQClient(api_key=os.environ["ARMORIQ_API_KEY"], agent_id="support-agent")

    with client.start_session(SessionOptions(mode="sdk")) as session:
        ...  # your start_plan, check, and report calls
    ```
  </Tab>

  <Tab value="TypeScript">
