    {"id": "n1", "action": "fetch_data", "mcp": "data-mcp"},
    {"id": "n2", "action": "analyze", "mcp": "analytics-mcp"}
  ],
  "edges": [
    {"from": "n1", "to": "n2"}
  ]
}
```

