# Connection Pooling [#connection-pooling]

The ArmorIQ SDK maintains an internal HTTP connection pool per client. In most
cases, a **single shared client instance** is the right answer - see
[Client Lifecycle Management](/sdk/best-practices/client-lifecycle-management).

If you specifically need a pool of client instances (e.g. sharding across
API keys or isolating per-tenant token caches), here's a minimal pattern:

<Tabs groupId="language" items="['Python', 'TypeScript']">
  <Tab value="Python">
    ```python
    from armoriq_sdk import ArmorIQClient
    import threading

    class ArmorIQClientPool:
        def __init__(self, api_key, pool_size=5):
            self.api_key = api_key
            self.pool = [ArmorIQClient(api_key=api_key) for _ in range(pool_size)]
            self.lock = threading.Lock()
            self.available = list(self.pool)

        def get_client(self):
            with self.lock:
                if self.available:
                    return self.available.pop()
                # Pool exhausted, create new client
                return ArmorIQClient(api_key=self.api_key)

        def return_client(self, client):
            with self.lock:
                self.available.append(client)

    # Usage
    pool = ArmorIQClientPool(api_key="ak_live_...", pool_size=10)

    def process_task(user_email, task):
        client = pool.get_client()
        try:
            # Attribute the call to the end user without binding the pooled client
            return client.invoke(mcp, action, token, params, user_email=user_email)
        finally:
            pool.return_client(client)
    ```
  </Tab>

  <Tab value="TypeScript">
    ```typescript
    import { ArmorIQClient } from '@armoriq/sdk';

    class ArmorIQClientPool {
      private pool: ArmorIQClient[] = [];
      private available: ArmorIQClient[] = [];
      private apiKey: string;

      constructor(apiKey: string, poolSize: number = 5) {
        this.apiKey = apiKey;
        for (let i = 0; i < poolSize; i++) {
          const client = new ArmorIQClient({ apiKey });
          this.pool.push(client);
          this.available.push(client);
        }
      }

      getClient(): ArmorIQClient {
        if (this.available.length > 0) {
          return this.available.pop()!;
        }
        // Pool exhausted, create new client
        return new ArmorIQClient({ apiKey: this.apiKey });
      }

      returnClient(client: ArmorIQClient): void {
        this.available.push(client);
      }

      closeAll(): void {
        this.pool.forEach(client => client.close());
        this.pool = [];
        this.available = [];
      }
    }

    // Usage
    const pool = new ArmorIQClientPool(process.env.ARMORIQ_API_KEY!, 10);

    async function processTask(userEmail: string, task: any) {
      const client = pool.getClient();
      try {
        // 5th arg is merkleProof (optional); 6th attributes the call to the end user
        return await client.invoke('mcp', 'action', token, {}, undefined, userEmail);
      } finally {
        pool.returnClient(client);
      }
    }
    ```
  </Tab>
</Tabs>

<Callout type="info">
  Per-user state (policy context, approver chain) lives on the
  `for_user(email)` scope, not on the client, so one pool of clients can
  safely serve many users.
</Callout>

# Token Caching [#token-caching]

Implement token caching to avoid redundant token requests. Cache tokens by plan hash and reuse them until they're close to expiration.

<Tabs groupId="language" items="['Python', 'TypeScript']">
  <Tab value="Python">
    ```python
    import time
    from typing import Dict, Tuple

    class TokenCache:
        def __init__(self):
            self.cache: Dict[str, Tuple[str, int]] = {}

        def get(self, plan_hash: str) -> str | None:
            if plan_hash in self.cache:
                token, expires_at = self.cache[plan_hash]
                # Return token if valid for at least 60 more seconds
                if time.time() < expires_at - 60:
                    return token
            return None

        def set(self, plan_hash: str, token: str, expires_at: int):
            self.cache[plan_hash] = (token, expires_at)

        def clear_expired(self):
            now = time.time()
            self.cache = {
                k: v for k, v in self.cache.items()
                if v[1] > now
            }

    # Usage
    token_cache = TokenCache()

    def get_token_cached(client, llm, prompt):
        captured = client.capture_plan(llm=llm, prompt=prompt)
        plan_hash = captured.plan_hash

        # Try cache first
        token = token_cache.get(plan_hash)
        if token:
            return token

        # Get new token
        response = client.get_intent_token(captured)
        token_cache.set(plan_hash, response["token"], response["expires_at"])

        return response["token"]
    ```
