The working version of every file in this guide, including this one, lives in `armoriq-adk-ops-agent`. Clone it if you'd rather start from something that runs.

```typescript
/**
 * ═══════════════════════════════════════════════════════════════════════════
 *  This is the file to read.
 * ═══════════════════════════════════════════════════════════════════════════
 *
 * A Google ADK agent, governed by ArmorIQ, in four steps:
 *
 *   Step 1  Get the tools from the MCP server
 *   Step 2  Build the ADK agent
 *   Step 3  Wrap the run in ArmorIQ          <-- the integration
 *   Step 4  Run it and print what happened
 *
 * Only step 3 is ArmorIQ. Steps 1, 2 and 4 are ordinary ADK code. If you
 * deleted step 3 the agent would still work, it just would not be governed.
 *
 * How ArmorIQ governs the agent: `scope.install(agent)` attaches three
 * callbacks to the agent.
 *
 *   afterModelCallback   after the model picks tools, describe them as a
 *                        "plan" and get it cryptographically signed
 *   beforeToolCallback   before each tool runs, ask ArmorIQ: allow, hold
 *                        (wait for a human), or block?
 *   afterToolCallback    after each tool runs, record what happened
 *
 * The important part: enforcement happens in `beforeToolCallback`, which is
 * outside the model. It does not matter what the model was persuaded to do.
 */
import {
  InMemorySessionService,
  LlmAgent,
  MCPToolset,
  Runner,
  getFunctionCalls,
  getFunctionResponses,
  isFinalResponse,
} from '@google/adk';
import { ArmorIQADK, ArmorIQADKBundle } from '@armoriq/sdk/dist/integrations/google_adk';

import { config } from './config.js';

const APP_NAME = 'ops-copilot';

const INSTRUCTIONS = `
You are the internal operations copilot for a SaaS company. You help support
staff resolve customer billing problems.

How to work:
- Look up the customer and their charges before you act.
- Read the support ticket that was referenced, so you know what was asked.
- If you find a duplicate charge, refund exactly the duplicated amount.
- Be brief. Say what you did, and what you could not do.

Some actions are governed by company policy. A tool may come back refused or
held for human approval. If that happens, do not retry it and do not look for a
way around it. Explain it plainly and carry on with what you can do.
`.trim();

export type AskResult = {
  answer: string;
  toolCalls: number;
  blocked: string[];
};

/**
 * Ask the agent one question.
 *
 * @param question    What the support person is asking for.
 * @param userEmail   Who is asking. ArmorIQ applies THAT person's policy, so
 *                    the same question can be allowed for one user and held for
 *                    another.
 */
export async function ask(question: string, userEmail: string): Promise<AskResult> {
  // ── Step 1: get the tools from the MCP server ─────────────────────────────
  // ADK connects to the MCP server and asks it what tools it has. We never
  // hand-write the tool list.
  const toolset = new MCPToolset({
    type: 'StreamableHTTPConnectionParams',
    url: config.mcpUrl,
  });
  const tools = await toolset.getTools();
  console.log(`Found ${tools.length} tools on the MCP server.\n`);

  // ── Step 2: build the ADK agent ───────────────────────────────────────────
  const agent = new LlmAgent({
    name: 'ops_copilot',
    model: config.model,
    instruction: INSTRUCTIONS,
    tools,
  });

  const sessionService = new InMemorySessionService();
  const runner = new Runner({ appName: APP_NAME, agent, sessionService });
  const session = await sessionService.createSession({ appName: APP_NAME, userId: userEmail });

  // ── Step 3: wrap the run in ArmorIQ ───────────────────────────────────────
  const blocked: string[] = [];

  // If ArmorIQ is disabled, `armoriq` stays undefined and nothing below runs.
  let armoriq: ArmorIQADK | undefined;
  if (!config.disableArmoriq) {
    armoriq = new ArmorIQADK({
      apiKey: config.armoriqApiKey,
      agentName: config.agentName,
      defaultMcpName: config.mcpName,
      approvalWaitSeconds: config.approvalWaitSeconds,
    });
  }

  // `scope` is only set when ArmorIQ is enabled. Everything below that uses
  // it is guarded by `if (scope)`.
  let scope: ArmorIQADKBundle | undefined;

  if (armoriq) {
    // `forUser` binds this run to one person, so policy is applied per user.
    scope = await armoriq.forUser(userEmail, {
      goal: question,
      // Optional. ArmorIQ calls this as it makes decisions, so an app can show
      // "waiting for approval" instead of appearing frozen.
      onEvent: (kind, payload) => {
        const tool = String(payload.tool ?? '');
        if (kind === 'hold') {
          console.log(`HOLD     ${tool} - waiting for a human to approve`);
          console.log(`         reason: ${payload.reason}`);
        } else if (kind === 'approved') {
          console.log(`APPROVED ${tool} - carrying on`);
        } else if (kind === 'block') {
          blocked.push(tool);
          console.log(`BLOCKED  ${tool}`);
          console.log(`         reason: ${payload.reason}`);
        } else if (kind === 'timeout' || kind === 'rejected') {
          blocked.push(tool);
          console.log(`REFUSED  ${tool} - approval ${kind}`);
        }
      },
    });

    scope.install(agent);
  } else {
    console.log('ArmorIQ is NOT installed. Nothing will be checked.\n');
  }

  // ── Step 4: run it ────────────────────────────────────────────────────────
  let answer = '';
  let toolCalls = 0;

  try {
    for await (const event of runner.runAsync({
      userId: userEmail,
      sessionId: session.id,
      newMessage: { role: 'user', parts: [{ text: question }] },
    })) {
      // Log each tool the model decided to call.
      for (const call of getFunctionCalls(event)) {
        toolCalls += 1;
        console.log(`CALL     ${call.name} ${JSON.stringify(call.args ?? {})}`);
      }

      // Log each result. A refused tool comes back with an `armoriq_enforcement`
      // field instead of real data. ArmorIQ returns the refusal to the model
      // rather than throwing, so the agent can explain itself.
      for (const response of getFunctionResponses(event)) {
        const result = response.response as Record<string, unknown> | undefined;
        if (result && !result.armoriq_enforcement) {
          console.log(`ALLOWED  ${response.name}`);
        }
      }

      if (isFinalResponse(event)) {
        let text = '';
        if (event.content?.parts) {
          text = event.content.parts.map((p) => p.text ?? '').join('');
        }
        if (text.trim()) answer = text.trim();
      }
    }
  } finally {
    // Always clean up, even if the run failed.
    if (scope) {
      scope.uninstall(agent);
      await scope.close();
    }
    await toolset.close();
  }

  return { answer, toolCalls, blocked };
}
```

`src/mcp.js` owns the connection to GitHub's tools. It spawns the MCP server as a local child process over stdio, and gives you three functions: list the tools it exposes, call one, and disconnect when you're done.

```js
// src/mcp.js
import { Client } from "@modelcontextprotocol/sdk/client/index.js";
import { StdioClientTransport } from "@modelcontextprotocol/sdk/client/stdio.js";

let mcpClient = null;
let mcpTransport = null;

export async function connectGitHubMcp(githubToken) {
  if (mcpClient) return mcpClient;

  mcpTransport = new StdioClientTransport({
    command: "npx",
    args: ["-y", "@modelcontextprotocol/server-github"],
    env: { ...process.env, GITHUB_PERSONAL_ACCESS_TOKEN: githubToken },
  });

  mcpClient = new Client(
    { name: "armoriq-github-agent", version: "1.0.0" },
    { capabilities: {} }
  );
  await mcpClient.connect(mcpTransport);
  return mcpClient;
}

export async function listTools() {
  const result = await mcpClient.listTools();
  return result.tools;
}

export async function callTool(toolName, args) {
  return mcpClient.callTool({ name: toolName, arguments: args });
}

export async function disconnectGitHubMcp() {
  if (mcpTransport) {
    await mcpTransport.close();
    mcpTransport = null;
    mcpClient = null;
  }
}
```

The first time this runs, `npx` downloads the GitHub MCP server package, so expect a short delay on the very first call.

`src/planner.js` turns a plain-English goal, `"list commits for acme/widgets"`, into a structured tool call the MCP server understands: `{ name: "list_commits", args: { owner: "acme", repo: "widgets" } }`.

````js
// src/planner.js

const GITHUB_MCP_TOOLS = [
  { name: "search_repositories", description: "Search repositories (args: { query })" },
  { name: "list_commits", description: "List commits in a repository (args: { owner, repo })" },
  { name: "list_issues", description: "List issues in a repository (args: { owner, repo })" },
  { name: "get_file_contents", description: "Get a file or directory (args: { owner, repo, path })" },
];

async function planWithGemini(goal, geminiApiKey) {
  const prompt = `Convert this goal into GitHub MCP tool calls.
Available tools: ${JSON.stringify(GITHUB_MCP_TOOLS)}
Goal: "${goal}"
Return ONLY a JSON array like [{ "name": "tool_name", "args": {} }]. No markdown, no extra text.`;

  const url = `https://generativelanguage.googleapis.com/v1beta/models/gemini-flash-latest:generateContent?key=${geminiApiKey}`;
  const response = await fetch(url, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ contents: [{ parts: [{ text: prompt }] }] }),
  });

  const data = await response.json();
  const raw = data.candidates?.[0]?.content?.parts?.[0]?.text?.trim() ?? "";
  const clean = raw.replace(/```json|```/g, "").trim();
  return JSON.parse(clean);
}

/**
 * `overrides` carries values you already know exactly (a repo the user
 * picked from a list, a file path they typed) and always wins over
 * whatever the LLM extracted from free text. Never trust free-text
 * extraction alone for a value your policy needs to be exact.
 */
export async function planWithLlm(goal, overrides = {}) {
  const [call] = await planWithGemini(goal, process.env.GEMINI_API_KEY);
  if (!call?.name) throw new Error(`The model returned no usable tool call for: ${goal}`);
  return [{ ...call, args: { ...call.args, ...overrides } }];
}
````

> **Using a different LLM?** Only `planWithGemini` changes. Everything downstream expects the same return shape: an array of `{ name, args }` objects.

Every step follows the same four moves: **plan → check → execute → report**. Put that in one reusable function in `agent.js`.

```js
// agent.js
import readline from "node:readline/promises";
import dotenv from "dotenv";
import { ArmorIQClient } from "@armoriq/sdk";
import { connectGitHubMcp, callTool, disconnectGitHubMcp } from "./src/mcp.js";
import { planWithLlm } from "./src/planner.js";

dotenv.config();

const userEmail = process.env.USER_EMAIL;

const rl = readline.createInterface({ input: process.stdin, output: process.stdout });
const askUser = (question) => rl.question(question);

async function runStep(session, goal, overrides) {
  const [call] = await planWithLlm(goal, overrides);

  // 1. Commit this step to the plan ArmorIQ is tracking.
  await session.startPlan([call], goal);

  // 2. Check policy before anything executes.
  const decision = await session.check(call.name, call.args, userEmail);
  if (!decision.allowed) {
    console.log(`[BLOCKED] ${call.name}: ${decision.reason}`);
    await session.report(call.name, call.args, null, { status: "failed", errorMessage: decision.reason });
    return null;
  }

  // 3. Execute the tool call yourself; this is what sdk mode means.
  const result = await callTool(call.name, call.args);
  const data = JSON.parse(result.content[0].text);

  // 4. Report the outcome for the audit trail.
  await session.report(call.name, call.args, data);
  return data;
}
```

Now use it to build the interactive walkthrough:

```js
async function main() {
  const armoriq = new ArmorIQClient({ apiKey: process.env.ARMORIQ_API_KEY });
  await armoriq.bootstrap();
  await connectGitHubMcp(process.env.GITHUB_PERSONAL_ACCESS_TOKEN);

  const session = armoriq.forUser(userEmail).startSession({
    mode: "sdk",
    defaultMcpName: "github",
    validitySeconds: 2400,
  });

  // Step 1: search, then let the user choose a repo.
  const search = await runStep(session, `Search repositories for ${process.env.GITHUB_USER}`, {});
  const repos = search.items;
  repos.forEach((r, i) => console.log(`  ${i + 1}. ${r.full_name}`));

  const choice = await askUser("\nWhich repository? ");
  const chosen = repos[Number(choice) - 1] ?? repos.find((r) => r.full_name.includes(choice));
  const owner = chosen.owner.login;
  const repo = chosen.name;

  // Step 2: list its commits.
  const commits = await runStep(session, `List commits for ${owner}/${repo}`, { owner, repo });
  commits.forEach((c) => console.log(`  ${c.sha.slice(0, 7)} ${c.commit.message.split("\n")[0]}`));

  // Step 3: list its issues.
  const issues = await runStep(session, `List issues for ${owner}/${repo}`, { owner, repo });
  issues.forEach((iss) => console.log(`  #${iss.number} [${iss.state}] ${iss.title}`));

  // Step 4: list files, then read the one the user asks for.
  const files = await runStep(session, `List files in ${owner}/${repo}`, { owner, repo, path: "" });
  files.forEach((f, i) => console.log(`  ${i + 1}. [${f.type}] ${f.path}`));

  const filePath = await askUser("\nWhich file would you like to read? ");
  const file = await runStep(session, `Get contents of ${filePath}`, { owner, repo, path: filePath });
  console.log(`\n--- ${filePath} ---\n${file.content}`);

  await session.flushObservability();
  await session.close();
  await disconnectGitHubMcp();
  rl.close();
}

main();
```

`askUser` is the small `node:readline/promises` helper defined at the top of the file; swap in any prompt library you already have.

